import {BUILD_STATS,buildDefaults,calculateBuild,craftedBonuses,skillClosure,removeSkill,skillBudget,skillCost,skillSelection,shopCap,shopAction,potionGroup,corruptedCost,corruptedRefund,corruptedRemainingCost,buyAllCorrupted,setCorruptedLevel} from './build.js?v=9.2';
const root=document.querySelector('#app'),KEY='cardborn-build-v2';
let data;try{const response=await fetch('./data/game.json?v=6.1');if(!response.ok)throw Error();data=await response.json()}catch{root.textContent='Game data could not load. Refresh this page.';throw Error('Game data unavailable')}
const labels={Luck:'Luck',ShinyLuck:'Shiny Luck',AwakenedLuck:'Awakened Luck',FabledLuck:'Fabled Luck',CorruptedLuck:'Corrupted Luck',VoidLuck:'Void Luck',RollSpeed:'Roll Speed reduction',DoubleRollChance:'Double Roll',RollTwiceChance:'Roll Twice',TripleRollChance:'Triple Roll',LuckyHandChance:'Lucky Hand',PotionPowerMult:'Potion power',PotionDurationMult:'Potion duration',RollInterval:'Roll interval',RaidFabledLuck:'Fabled Luck in raids'};
const name=k=>labels[k]||k.replace('LuckMult',' Luck multiplier'),esc=x=>String(x??'').replace(/[&<>"']/g,k=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[k]));
const fmt=(n,d=3)=>!Number.isFinite(n)?'—':n!==0&&(Math.abs(n)<.00001||Math.abs(n)>=1e12)?n.toExponential(3):new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(n);
const pct=n=>`${fmt(n*100,4)}%`,time=n=>{if(!Number.isFinite(n))return 'Unavailable';const [value,unit,digits]=n<60?[n,'second',1]:n<3600?[n/60,'minute',1]:n<86400?[n/3600,'hour',2]:n<31557600?[n/86400,'day',2]:[n/31557600,'year',2];return `${fmt(value,digits)} ${unit}${value===1?'':'s'}`};
let tab='setup',plan=null,worker=null,job=0,running=false,error='',notice='',artifactInput='game',breakdownStat='Luck',simulation=null,simSeed=1,simFixedSeed=false,treeSelected='',buildName='',setupSection='account',overviewTab='target',editorMode=false,simWorker=null,simParallelism=1,simRunning=false,simProgress=0,simId=0,simDuration=8,simUnit='hour',simRuns=1,simView='average',simRun=0,simResultsTab='rarities',optUnit='hour',showAllChanges=false,verification=null,verifying=false,verificationWorker=null,verificationId=0;
let treeDragging=false;
const disclosureState=new Map();
function fresh(){const p=defaults(data);p.build=buildDefaults();p.version=2;p.rolls=0;p.fabledMax=1e30;return normalize(p,data)}
function upgrade(raw){const p=normalize(raw,data);if(!['hits','borders'].includes(p.optimizer.objective))p.optimizer.objective='hits';if(!p.build){p.build=buildDefaults();p.build.passes.ArtifactSlots=p.artifact.gamepass;p.build.void.PASlots=p.artifact.voidSlots;p.build.observed={...p.stats};p.version=2;notice='Previous allocation and artifact kept. Fill in Card Index and the remaining build inputs to calculate your stats.'}return normalize(p,data)}
let s;try{const saved=localStorage.getItem(KEY)||localStorage.getItem('cardborn-stat-optimizer-v1');s=saved?upgrade(JSON.parse(saved)):fresh()}catch{s=fresh()}
function cancelSimulation(){simWorker?.cancel();simWorker=null;simRunning=false;simId++}
function cancelVerification(){verificationWorker?.cancel();verificationWorker=null;verifying=false;verificationId++}
function cancel(){cancelVerification();cancelSimulation();worker?.terminate();worker=null;running=false;job++}
function save(){simulation=null;cancel();s=normalize(s,data);s.stats=effective(s,data);try{localStorage.setItem(KEY,JSON.stringify(s))}catch{notice='Browser storage unavailable. Export your profile to keep it.'}plan=null;verification=null;error=''}
const compactUnits=[['No',1e30],['Oc',1e27],['Sp',1e24],['Sx',1e21],['Qi',1e18],['Qa',1e15],['T',1e12],['B',1e9],['M',1e6],['K',1e3]];
function compactNumber(value){const unit=compactUnits.find(([,scale])=>value>=scale);return unit?String(value/unit[1])+unit[0]:String(value)}
function parseCompact(value){const match=String(value).replace(/[,\s]/g,'').match(/^(\d+(?:\.\d*)?|\.\d+)(?:e([+-]?\d+))?(k|m|b|t|qa|qi|sx|sp|oc|no)?$/i);if(!match)return NaN;const scale=compactUnits.find(([u])=>u.toLowerCase()===match[3]?.toLowerCase())?.[1]||1;return Number(match[1])*(match[2]?10**Number(match[2]):1)*scale}
const field=(id,label,value,{min=0,max='',step='any',unit='',help='',compact=false}={})=>`<label class="field" for="${id}"><span>${esc(label)}</span><div class="input-wrap"><input id="${id}" data-field="${id}" type="${compact?'text':'number'}" inputmode="${compact?'text':'decimal'}" min="${min}" ${max!==''?`max="${max}"`:''} step="${step}" value="${compact?compactNumber(value):value??''}">${unit?`<b>${esc(unit)}</b>`:''}</div>${help?`<small>${esc(help)}</small>`:''}</label>`;
const check=(id,label,on,help='')=>`<label class="check"><input id="${esc(id)}" data-field="${esc(id)}" type="checkbox" ${on?'checked':''}><span>${esc(label)}${help?`<small>${esc(help)}</small>`:''}</span></label>`;
const select=(id,label,options,value,help='')=>`<label class="field" for="${id}"><span>${esc(label)}</span><select id="${id}" data-field="${id}">${options.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</label>`;
const panel=(title,html,{open=false,caption=''}={})=>editorMode?`<section class="panel editor-panel"><div class="section-heading"><h2>${esc(title)}</h2>${caption?`<span class="badge">${esc(caption)}</span>`:''}</div><div class="panel-body">${html}</div></section>`:`<details class="panel" data-disclosure="${esc(title)}" ${open?'open':''}><summary>${esc(title)}${caption?`<small>${esc(caption)}</small>`:''}</summary><div class="panel-body">${html}</div></details>`;
const sections=[['account','Account','Index, rolls & stat points','Your build'],['skills','Skill tree','Nodes & constellations','Your build'],['equipment','Artifact & relics','Crafted equipment','Equipment'],['artifact','Personal Artifact','Slots & upgrades','Equipment'],['potions','Potions','Active boosts','Equipment'],['shops','Tower & Void shops','Gold & permanent upgrades','Progression'],['corrupted','Corrupted shop','Coins & owned upgrades','Progression'],['sets','Index sets','Completed collections','Progression'],['achievements','Achievements','Earned bonus rewards','Progression'],['world','World & Dungeon','Weather, access & floors','Progression']];
function setupWorkspace(){const entry=sections.find(x=>x[0]===setupSection);editorMode=true;const content=({account,skills,equipment,artifact,potions,shops,corrupted:pending,sets,achievements,world})[setupSection]();editorMode=false;return `<div class="setup-workspace"><label class="mobile-section-picker field"><span>Section</span><select id="setup-section">${sections.map(x=>`<option value="${x[0]}" ${x[0]===setupSection?'selected':''}>${x[1]}</option>`).join('')}</select></label><nav class="section-nav" aria-label="Setup sections">${sections.map((x,i)=>`${i===0||x[3]!==sections[i-1][3]?`${i===0?'':`<span class="nav-group">${x[3]}</span>`}`:''}<button data-section="${x[0]}" class="${x[0]===setupSection?'active':''}" aria-current="${x[0]===setupSection?'page':'false'}"><b>${x[1]}</b></button>`).join('')}</nav><div class="section-editor">${content}</div></div>`}
function overview(){return `<div class="overview-tabs"><button data-overview="target" class="${overviewTab==='target'?'active':''}">Target & odds</button><button data-overview="stats" class="${overviewTab==='stats'?'active':''}">All stats</button></div>${overviewTab==='target'?target()+hitResults():stats()}`}
const short=n=>{const unit=compactUnits.find(([,scale])=>n>=scale);return unit?fmt(n/unit[1],2)+unit[0]:fmt(n,2)};
const bonuses=o=>Object.entries(o||{}).map(([k,v])=>`${name(k)} ${CHANCES.includes(k)||k.startsWith('Potion')?pct(v):fmt(v)}`).join(' · ');
function account(){return panel('Account & stat points',`<div class="grid">${field('build-index','Card Index (unique entries)',s.build.index,{step:1,help:'2 skill points per 20 Index entries.'})}</div><p>Skill points: <b id="skill-earned">${skillBudget(s.build,data)}</b> · Spent: <b id="skill-spent">${skillCost(s.build.skills,data)}</b> · Available: <b id="skill-available">${skillBudget(s.build,data)-skillCost(s.build.skills,data)}</b></p><div class="grid">${field('rolls','Lifetime rolls',s.rolls,{step:1,help:'1 stat point per 50,000 rolls.'})}</div><p>Earned points: <b>${fmt(Math.floor(s.rolls/data.rollsPerPoint),0)}</b> · Spent: <b>${sum(s.points)}</b> · Cap stage: <b>${currentTier(s.points,data)+1}/8</b></p><h3>Fabled border availability</h3>${field('fabled-max','Cards rollable as Fabled through base rarity',s.fabledMax,{min:0,compact:true,help:'Cards at or below this rarity can roll Fabled. Enter 1B or 500M; 0 disables it.'})}<div class="grid four">${POINTS.map(k=>field('point-'+k,k+' points',s.points[k],{step:1,max:data.pointCaps[currentTier(s.points,data)][k],help:`+${data.pointGains[k]} per point`})).join('')}</div><p class="note">Fill all four caps to unlock the next stage.</p><div class="checks">${data.gamepasses.map(p=>check('pass-'+p.passKey,p.name,s.build.passes[p.passKey])).join('')}${check('build-under10M','Under-10M rolls Luck boost',s.build.under10M,'×1.25 Luck below 10M rolls.')}</div>`,{open:true})}
function skills(){const owned=new Set(s.build.skills),positions=new Map(),groups=['Fortune','Velocity','Radiance','Mythos','Corrupted','Alchemy'];for(let j=0;j<groups.length;j++){const nodes=data.skillNodes.filter(n=>n.branch===groups[j]),core=nodes.filter(n=>n.path==='Core'),paths=[...new Set(nodes.filter(n=>!['Core','Mastery'].includes(n.path)).map(n=>n.path))],x=110+j*175;core.forEach((n,i)=>positions.set(n.id,{x,y:760-i*75}));paths.forEach((p,k)=>nodes.filter(n=>n.path===p).forEach((n,i)=>positions.set(n.id,{x:x+(k===0?-42:42),y:510-i*75})));for(const n of nodes.filter(n=>n.path==='Mastery'))positions.set(n.id,{x,y:170})}data.skillNodes.filter(n=>n.branch==='Grandmastery').forEach((n,i)=>positions.set(n.id,{x:500+i*100,y:95}));data.skillNodes.filter(n=>n.branch==='Transcendence').forEach((n,i)=>positions.set(n.id,{x:220+i*110,y:35}));const selected=data.skillNodes.find(n=>n.id===treeSelected),stars=data.skillNodes.filter(n=>n.branch==='Constellations');return panel('Skill tree',`<p><b id="skill-spent">${skillCost(s.build.skills,data)}</b> SP spent${skillBudget(s.build,data)!=null?` / ${skillBudget(s.build,data)} earned`:''}. Drag to pan. Click to select.</p><div class="tree-scroll"><svg class="skill-tree" viewBox="0 0 1120 855" aria-label="Interactive skill tree">${data.skillNodes.filter(n=>positions.has(n.id)).flatMap(n=>n.requires.filter(r=>positions.has(r)).map(r=>`<line x1="${positions.get(r).x}" y1="${positions.get(r).y}" x2="${positions.get(n.id).x}" y2="${positions.get(n.id).y}" class="${owned.has(n.id)?'owned':''}"/>`)).join('')}${groups.map((g,i)=>`<text x="${110+i*175}" y="825" class="branch-label">${g}</text>`).join('')}${data.skillNodes.filter(n=>positions.has(n.id)).map(n=>{const p=positions.get(n.id);return`<g data-tree-skill="${n.id}" role="button" tabindex="0" aria-label="${esc(n.name)}: ${esc(n.desc)}; ${n.cost} SP" aria-pressed="${owned.has(n.id)}" class="tree-node ${owned.has(n.id)?'owned':''}" transform="translate(${p.x},${p.y})"><circle r="19"/><text>${owned.has(n.id)?'✓':n.cost}</text></g>`}).join('')}</svg></div><p id="tree-selection">${selected?`<b>${esc(selected.name)}</b> · ${selected.cost} SP · ${esc(selected.desc)}`:''}</p><h3>Constellations · Normal ${stars.filter(n=>n.limitGroup==='star1'&&owned.has(n.id)).length}/2 · Greater ${stars.filter(n=>n.limitGroup==='star2'&&owned.has(n.id)).length}/1 · Ascendant ${stars.filter(n=>n.limitGroup==='star3'&&owned.has(n.id)).length}/1</h3><div class="constellation-grid">${['star1','star2','star3'].map((g,i)=>`<div><h3>${['Normal','Greater','Ascendant'][i]}</h3>${stars.filter(n=>n.limitGroup===g).map(n=>{const blocked=!owned.has(n.id)&&skillSelection(s.build,n.id,true,data).error;return`<label class="check"><input data-skill="${n.id}" type="checkbox" ${owned.has(n.id)?'checked':''} ${blocked?'disabled':''}><span>${esc(n.name)}<small>${esc(n.desc)} · ${n.cost} SP</small></span></label>`}).join('')}</div>`).join('')}</div><button data-clear-skills>Clear skill tree</button>`,{caption:`${owned.size} nodes`,open:true})}
function equipment(){const crafted=craftedBonuses(s.build,data);return panel('Crafted artifact & relics',`${select('build-crafted','Equipped crafted artifact',[['','None'],...Object.entries(data.craftedArtifacts).sort((a,b)=>a[1].Order-b[1].Order).map(([id,d])=>[id,d.Name])],s.build.crafted)}<div class="grid">${select('build-craftedTier','Crafted tier',data.craftedTiers.map(t=>[t.id,`${t.label} · +${t.boost}% stats`]),s.build.craftedTier)}${field('build-craftedIndexPoints','Artifact Index points',s.build.craftedIndexPoints,{step:1,max:Object.keys(data.craftedArtifacts).length*data.craftedTiers.length,help:''})}</div><p id="crafted-index-summary">Artifact Index: <b>${s.build.craftedIndexPoints} points · +${crafted.indexPercent}%</b> · Next bonus: ${crafted.pointsToNext} ${crafted.pointsToNext===1?'point':'points'}</p>${s.build.crafted?`<p id="crafted-tier-preview"><b>Tier stats:</b> ${esc(bonuses(crafted.preview))}</p><p id="crafted-applied-preview"><b>Equipped stats:</b> ${esc(bonuses(crafted.flat))}</p>`:''}<p class="note">Index: +10% per 2 points. Tier/Index stacking is estimated.</p>${s.build.relics.map((r,i)=>`<div class="equipment-row"><label class="field"><span>Relic ${i+1}</span><select data-relic="${i}" data-part="id">${Object.entries(data.relics).map(([id,d])=>`<option value="${id}" ${id===r.id?'selected':''}>${esc(d.Name)}</option>`).join('')}</select></label><label class="field"><span>Border</span><select data-relic="${i}" data-part="border">${data.relicBorders.map((label,j)=>`<option value="${j+1}" ${j+1===r.border?'selected':''}>${label}</option>`).join('')}</select></label><button data-remove-relic="${i}" aria-label="Remove relic ${i+1}">Remove</button><small>${esc(data.relics[r.id].Desc)} · Border scale ×${(data.relics[r.id].BorderScale||[1,1.4,1.9,2.5,3.2,4])[r.border-1]}</small></div>`).join('')}<button data-add-relic ${s.build.relics.length>=3?'disabled':''}>Add relic</button><p class="note">Up to 3 relics; max 2 Legendary.</p>`,{caption:`${s.build.relics.length} relics`})}
function artifact(){const level=artifactLevel(s,data),slots=artifactSlots(s,data),defs=data.personalArtifact.stats,next=level>=100?null:Math.ceil(((level+1)/100)**(1/data.personalArtifact.levelExponent)*data.personalArtifact.rollsForMaxLevel),base=data.personalArtifact.slotUnlockLevels.filter(l=>l<=level).length,rarity=data.personalArtifact.rarities.find(d=>d.id===s.artifact.rarity);return panel('Personal Artifact',`<p><b>Level ${level} / 100</b> · Upgrade cap: <b>${level}%</b> of the full range${next!=null?` · ${fmt(next-s.rolls,0)} rolls until level ${level+1}`:''}</p><progress value="${level}" max="100"></progress><p><b>${slots} fixed slots</b>: ${base} level slots + ${s.artifact.gamepass?2:0} gamepass + ${base?rarity.bonusSlots:0} rarity + ${base?s.artifact.voidSlots:0} Void Shop. Level milestones: 1 / 15 / 35 / 60 / 90.</p><div class="grid">${select('artifact-rarity','Rarity',data.personalArtifact.rarities.map(d=>[d.id,`${d.name} · ${d.statMultiplier}×`]),s.artifact.rarity)}${select('artifact-input','Enter stat values as',[['game','In-game value'],['raw','Base value'],['quality','Quality %']],artifactInput)}</div><p class="note">Enter the values shown on your PA.</p>${s.artifact.slots.map((slot,i)=>{const def=defs.find(d=>d.id===slot.id),max=def?scaledMax(def,level):0,quality=def?(slot.value-def.min)/(def.max-def.min)*100:0,shown=def?paDisplayValue(s,def,slot.value,data):0,shownMax=def?paDisplayValue(s,def,max,data):0,shownMin=def?paDisplayValue(s,def,def.min,data):0;return`<div class="artifact-row"><label class="field"><span>Slot ${i+1}</span><select data-slot="${i}" data-part="id"><option value="">Empty</option>${defs.map(d=>`<option value="${d.id}" ${d.id===slot.id?'selected':''}>${esc(name(d.id))}</option>`).join('')}</select></label><label class="field"><span>${artifactInput==='game'?'In-game value'+paUnit(def):artifactInput==='raw'?'Base value':'Quality %'}</span><input data-slot="${i}" data-part="value" type="number" value="${artifactInput==='game'?shown:artifactInput==='raw'?slot.value:Number(quality.toFixed(3))}" min="${artifactInput==='game'?shownMin:def&&artifactInput==='raw'?def.min:0}" max="${artifactInput==='game'?shownMax:artifactInput==='raw'?max:level}" step="any" ${def?'':'disabled'}></label><label class="check keep"><input data-slot="${i}" data-part="locked" type="checkbox" ${slot.locked?'checked':''} ${def?'':'disabled'}><span>Keep</span></label>${def?`<small>Allowed ${artifactInput==='game'?fmt(shownMin):def.min}–${artifactInput==='game'?fmt(shownMax):max} · ${Math.round(quality)}% quality</small>`:''}</div>`}).join('')}`,{caption:`${slots} slots`,open:true})}
function shops(){const shop=(key,title,defs)=>`<h3>${title}</h3>${field('currency-'+key,key==='tower'?'Unspent gold':'Unspent Void Coins',s.build.currencies[key],{step:1})}<p class="note">Enter owned levels. Buying uses your balance${key==='tower'?'; refunds return gold':'; no Void refunds'}.</p><div class="shop-grid">${defs.map(d=>{const lv=s.build[key][d.id]||0,cap=shopCap(s.build,d,key),can=lv<cap&&s.build.currencies[key]>=d.cost;return`<div class="shop-upgrade">${field(key+'-'+d.id,'Owned '+d.name,lv,{step:1,max:cap,help:`${key==='tower'?(d.id==='AwakenedLuck'?'+0.4 Awakened Luck per level':d.desc):d.desc} · cap ${cap}`})}<div class="shop-buttons">${key==='tower'?`<button data-shop="tower" data-upgrade="${d.id}" data-direction="-1" ${lv?'':'disabled'}>− Refund ${d.cost}g</button>`:''}<button data-shop="${key}" data-upgrade="${d.id}" data-direction="1" ${can?'':'disabled'}>+ Buy ${d.cost}${key==='tower'?'g':' Coins'}</button>${key==='tower'?`<button data-shop="tower" data-upgrade="${d.id}" data-direction="max" ${can?'':'disabled'}>Buy max</button>`:''}</div></div>`}).join('')}</div>`;return panel('Tower & Void Shop',shop('tower','Tower Shop',data.towerShop)+shop('void','Void Shop',data.voidShop))}
function sets(){return panel('Completed Index Sets',`<button data-sets-all>Select all sets</button><button data-sets-clear>Clear sets</button><div class="checks">${data.indexSets.map(d=>check('set-'+d.id,d.name,s.build.sets.includes(d.id),bonuses(d.bonus))).join('')}</div>`,{caption:`${s.build.sets.length}/${data.indexSets.length}`})}
function potions(){const groups=[...new Set(Object.keys(data.potions).filter(id=>Object.keys(data.potions[id].Boosts).length).map(id=>potionGroup(id,data)))];return panel('Active potions & temporary buffs',`<div class="grid">${groups.map(group=>select('potion-'+group,group.endsWith('Mythic')?'Mythic '+name(group.slice(0,-6)):group==='LuckOrb'?'Parkour Orb':group==='HeavenlyLuck'?'Heavenly Luck':name(group),[['','None'],...Object.entries(data.potions).filter(([id,d])=>potionGroup(id,data)===group&&Object.keys(d.Boosts).length).map(([id,d])=>[id,d.Name])],s.build.potions.find(id=>potionGroup(id,data)===group)||'')).join('')}</div><p class="note">Mythic Shiny and Awakened stack with regular or Legendary potions.</p>`)}
const badges=[...new Set(data.cards.map(c=>c.badgeRequired).filter(Boolean))];
function world(){return panel('Weather, worlds & Dungeon',`${select('weather','Current weather',[['Clear','No special weather'],...Object.keys(data.weather).map(id=>[id,id.replace(/([a-z])([A-Z])/g,'$1 $2')])],s.weather)}<h3>Unlocked worlds</h3><div class="checks">${badges.map(b=>check('badge-'+b,b.replace('Badge','').replace(/([a-z])([A-Z])/g,'$1 $2'),s.badges.includes(b))).join('')}</div><h3>Infinite Dungeon</h3>${check('build-inDungeon','Enable Infinite Dungeon floor preview',s.build.inDungeon)}${field('build-floor','Highest floor reached',s.build.floor,{step:1})}<label class="field"><span>Time to reach that floor (hours:minutes:seconds)</span><input id="dungeon-time" value="${duration(s.build.dungeonSeconds)}" placeholder="01:00:00" pattern="[0-9]+:[0-5][0-9]:[0-5][0-9]" ${s.build.inDungeon?'':'disabled'}></label><p class="note">${s.build.inDungeon?`${fmt(3600/s.build.dungeonSeconds,2)} runs/hour at this duration. `:''}Floor bonuses are estimates.</p>`)}
function target(includeSession=true){return `<section class="panel plain"><h2>Target</h2><div class="grid">${select('goal-kind','Target type',[['rarity','Minimum base rarity'],['card','Specific card']],s.goal.kind)}${s.goal.kind==='rarity'?field('goal-rarity','Minimum base rarity',s.goal.rarity,{min:1,compact:true}):`<label class="field"><span>Card</span><input id="goal-card" data-field="goal-card" list="card-list" value="${esc(s.goal.card)}"><datalist id="card-list">${data.cards.map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist></label>`}</div><div class="border-choices">${BORDERS.map(k=>check('border-'+k,k,s.goal.borders.includes(k))).join('')}</div><p class="note">Requires all selected borders. Rarity is before borders.</p><div class="grid">${field('global-luck','Global Luck multiplier',s.globalLuck,{min:.0001,max:1000,unit:'×',help:'Use the multiplier shown in-game; 1 means none.'})}${includeSession?field('minutes','Session length',s.minutes,{min:.01,unit:'minutes'}):''}${effective(s,data).periodic.length?field('roll-counter','Starting roll counter',s.rollCounter,{step:1,help:'For periodic boosts; 0 starts a fresh cycle.'}):''}</div></section>`}
function stats(){const calculated=calculateBuild(s,data,s.points,artifactBonuses(s,s.artifact.slots,data)),v=calculated.stats,keys=[...LUCKS,'RollSpeed','RollInterval',...CHANCES,'PotionPowerMult','PotionDurationMult'];return `<section class="panel plain"><h2>Current stats</h2><table class="stat-table"><tbody>${keys.map(k=>`<tr><th>${name(k)}</th><td><output id="total-${k}">${CHANCES.includes(k)?pct(v[k]):fmt(v[k])+(k==='RollSpeed'||k==='RollInterval'?'s':k.startsWith('Potion')?'×':'')}</output></td></tr>`).join('')}${calculated.raidMult>1?`<tr><th>Fabled Luck in raids</th><td>${fmt(v.RaidFabledLuck)}</td></tr>`:''}</tbody></table>${calculated.periodic.map(d=>`<p class="note">Every ${d.every} rolls: ×${d.mult} Luck</p>`).join('')}</section>${panel('Calculation breakdown',`${select('breakdown-stat','Stat',BUILD_STATS.map(k=>[k,name(k)]),breakdownStat)}<table><thead><tr><th>Source</th><th>Flat</th><th>Bonus</th><th>Multiplier</th></tr></thead><tbody>${calculated.rows.filter(r=>r.flat[breakdownStat]||r.percent[breakdownStat]||r.mult[breakdownStat]&&r.mult[breakdownStat]!==1).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.flat[breakdownStat]!=null?fmt(r.flat[breakdownStat]):'—'}</td><td>${r.percent[breakdownStat]?pct(r.percent[breakdownStat]):'—'}</td><td>${r.mult[breakdownStat]!=null?fmt(r.mult[breakdownStat])+'×':'—'}</td></tr>`).join('')}</tbody></table><p class="note">Minimum roll interval: 0.2s.</p>`)}`}
function hitResults(){const r=evaluate(s,data);return `<section class="panel plain"><h2>Hit results</h2><table><tbody>${[['Chance per kept card',r.probability>0?'1 / '+fmt(1/r.probability):'Unavailable'],['Estimated average wait',time(r.averageSeconds)],['Hits per hour',fmt(r.hitsPerHour,6)],['Cards per hour',fmt(r.cardsPerHour)],[`Chance in ${fmt(s.minutes)} minutes`,pct(r.chance)],['50% chance by',time(r.medianSeconds)],['90% chance by',time(r.p90Seconds)]].map(([label,value])=>`<tr><th>${label}</th><td>${value}</td></tr>`).join('')}</tbody></table>${!r.probability?'<p class="note">Target unavailable with this setup.</p>':''}</section>`}
function optimizer(){const o=optimizerSettings(s,data);return `<section class="panel plain optimizer-config"><h2>Optimizer</h2><div class="optimizer-layout"><section class="optimizer-section"><h3>Goal</h3>${select('opt-objective','Optimize for',[['hits','Target card rarity'],['borders','Border combination']],o.objective)}${o.objective==='hits'?field('opt-rarity','Minimum rarity after borders',o.rarity,{min:1,compact:true}):`<div class="field" role="group" aria-label="Borders"><span>Borders</span><div class="border-choices">${BORDERS.map(k=>check('opt-border-'+k,k,o.borders.includes(k))).join('')}</div></div>${select('opt-match','Match',[['contains','Contains selected borders'],['exact','Exact combination']],o.match)}`}<div class="grid">${field('opt-hours','Result time',o.seconds/(optUnit==='day'?86400:3600),{min:60/(optUnit==='day'?86400:3600),max:172800/(optUnit==='day'?86400:3600)})}${select('opt-unit','Unit',[['hour','Hours'],['day','Days']],optUnit)}</div>${towerSettings(o.seconds)}</section><section class="optimizer-section"><h3>Allow changes</h3><div class="checks optimizer-scope">${Object.entries(COMPONENTS).map(([id,label])=>check('opt-component-'+id,label,o.components[id])).join('')}</div>${field('artifact-quality','Planned PA roll quality',s.artifact.quality*100,{max:100,unit:'%'})}<p class="note">PA Keep slots, equipped crafted artifact and active buffs stay fixed.</p><h3>Available resources</h3><div class="resource-grid">${[['Stat points',Math.floor(s.rolls/data.rollsPerPoint)],['Skill points',skillBudget(s.build,data)],['Gold',s.build.currencies.tower],['Void Coins',s.build.currencies.void],['Corrupted Coins',s.build.currencies.corrupted]].map(([label,value])=>`<div><small>${label}</small><b>${fmt(value,0)}</b></div>`).join('')}</div><button data-tab="setup">Edit setup</button></section></div>${availableEquipment(o)}<div class="sim-actions"><button class="primary" data-optimize="build" ${running?'disabled':''}>${running?'Optimizing…':'Optimize build'}</button>${running?'<button data-cancel-optimize>Cancel</button><span id="optimizer-progress" role="status">Starting…</span>':''}</div><p class="note">Final rarity includes all stacked borders. Build search and Tower reward rules are estimates.</p></section>${plan?recommendation():''}`}
function availableEquipment(o){const available=id=>o.relics.find(x=>x.id===id),equipped=id=>s.build.relics.some(x=>x.id===id);return `<details class="panel available-equipment" data-disclosure="Available equipment"><summary>Available relics</summary><div class="panel-body"><p class="note">Select what you own. Equipped relics are included.</p><div class="ownership-grid relic-ownership">${Object.entries(data.relics).map(([id,d])=>`<div class="ownership-row"><label class="check"><input type="checkbox" data-available="relics" data-item="${id}" ${available(id)?'checked':''} ${equipped(id)?'disabled':''}><span>${esc(d.Name)}</span></label><select data-owned-border="${id}" aria-label="${esc(d.Name)} border" ${available(id)?'':'disabled'}>${data.relicBorders.map((b,i)=>`<option value="${i+1}" ${i+1===available(id)?.border?'selected':''}>${b}</option>`).join('')}</select></div>`).join('')}</div></div></details>`}
const quantity=n=>n>0&&n<.001?n.toExponential(2):fmt(n,3);
function planMetric(result){return quantity(result.expectedHits)}
function planLabel(){const o=plan.settings;return `${o.objective==='hits'?'≥ '+short(o.rarity):(o.match==='exact'?'Exact ':'')+o.borders.join(' + ')} pulls in ${time(o.seconds)}`}
function recommendationRows(){const p=plan.profile,c=plan.original||s,rows=[],add=(system,label,a,b)=>rows.push({system,label,current:a,recommended:b,changed:a!==b});
  for(const k of POINTS)add('Stat points',k,c.points[k],p.points[k]);
  for(const node of data.skillNodes)add(node.branch==='Constellations'?'Constellation':'Skill tree',node.name,c.build.skills.includes(node.id)?'Owned':'—',p.build.skills.includes(node.id)?'Owned':'—');
  const relic=b=>b.relics.map(x=>data.relics[x.id].Name+' · '+data.relicBorders[x.border-1]);for(let i=0;i<Math.max(relic(c.build).length,relic(p.build).length);i++)add('Relics','Slot '+(i+1),relic(c.build)[i]||'None',relic(p.build)[i]||'None');
  const pa=(profile,i)=>{const slot=profile.artifact.slots[i],def=data.personalArtifact.stats.find(d=>d.id===slot?.id);return def?`${name(def.id)} · ${fmt(paDisplayValue(profile,def,slot.value,data))}${paUnit(def)}`:'Empty'};
  for(let i=0;i<Math.max(c.artifact.slots.length,p.artifact.slots.length);i++)add('Personal Artifact','Slot '+(i+1)+(p.artifact.slots[i]?.locked?' · kept':''),pa(c,i),pa(p,i));
  for(const [shop,label,defs]of [['tower','Tower Shop',data.towerShop],['void','Void Shop',data.voidShop],['corrupted','Corrupted Shop',data.corruptedUpgrades]])for(const d of defs)add(label,d.name,'Lv '+(c.build[shop][d.id]||0),'Lv '+(p.build[shop][d.id]||0));
  return rows;
}
function recommendation(){const p=plan.profile,c=plan.current,r=plan.result,ratio=plan.settings.objective==='highest'?10**(r.score-c.score):c.score?r.score/c.score:r.score?Infinity:1,rows=recommendationRows(),visible=showAllChanges?rows:rows.filter(row=>row.changed),metric=(label,value,best=false)=>`<div class="${best?'optimized':''}"><small>${label}</small><b>${value}</b></div>`;
  return `<section class="panel plain recommendation"><div class="results-heading"><div><span class="eyebrow">Recommended build</span><h2>${planLabel()}</h2></div><b class="improvement">${Number.isFinite(ratio)?'+'+fmt((ratio-1)*100,2)+'%':'New target'}</b></div><div class="comparison-metrics">${metric('Current',planMetric(c))}${metric('Optimized',planMetric(r),true)}${metric('Luck',short(c.stats.Luck)+' → '+short(r.stats.Luck))}${metric('Normal cards / sec',fmt((c.normalExpectedCards??c.expectedCards)/plan.settings.seconds,2)+' → '+fmt((r.normalExpectedCards??r.expectedCards)/plan.settings.seconds,2))}</div>${['hits','borders'].includes(plan.settings.objective)?`<div class="comparison-metrics">${metric('Chance of 1+ · current',pct(c.chance))}${metric('Chance of 1+ · optimized',pct(r.chance),true)}${metric('Normal qualifying pulls',quantity(c.normalHits)+' → '+quantity(r.normalHits))}${metric('Tower qualifying pulls',quantity(c.towerHits)+' → '+quantity(r.towerHits))}</div>`:''}<div class="resource-grid plan-resources">${[['Stat points',`${sum(p.points)} / ${Math.floor(p.rolls/data.rollsPerPoint)}`],['Skill points',`${skillCost(p.build.skills,data)} / ${skillBudget(p.build,data)}`],['Gold left',p.build.currencies.tower],['Void Coins left',p.build.currencies.void],['Corrupted Coins left',p.build.currencies.corrupted]].map(([label,value])=>metric(label,esc(value))).join('')}</div><div class="border-metrics comparison-stats">${LUCKS.slice(1).map((k,i)=>`<div style="--stat-color:${['#77dce6','#acbaff','#eec274','#d79af0','#99a3f9'][i]}"><span>${name(k)}</span><b>${fmt(c.stats[k],2)} → ${fmt(r.stats[k],2)}</b></div>`).join('')}</div><div class="results-toolbar"><h3>Build changes</h3><button data-show-changes>${showAllChanges?'Show changes only':'Show all upgrades'}</button></div><div class="table-scroll"><table class="change-table"><thead><tr><th>System</th><th>Upgrade</th><th>Current</th><th>Recommended</th></tr></thead><tbody>${visible.map(row=>`<tr class="${row.changed?'changed':''}"><td>${esc(row.system)}</td><td>${esc(row.label)}</td><td>${esc(row.current)}</td><td>${esc(row.recommended)}</td></tr>`).join('')||'<tr><td colspan="4">Current build kept.</td></tr>'}</tbody></table></div><div class="optimizer-buttons"><button class="primary" data-apply-plan>Apply build</button><button data-test-plan>Apply & simulate</button><button data-verify-plan ${verifying?'disabled':''}>${verifying?'Checking…':'Check with simulation'}</button>${verifying?'<button data-cancel-verification>Cancel check</button><span id="verification-progress" role="status">Starting…</span>':''}</div>${verification?verificationResults():''}${plan.opportunities.length?`<details class="next-upgrades"><summary>Next upgrades</summary><p class="note">These require new resources and are not applied.</p><table><thead><tr><th>Upgrade</th><th>Requires</th><th>Potential gain</th></tr></thead><tbody>${plan.opportunities.map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(x.requirement)}</td><td>+${fmt((x.gain-1)*100,2)}%</td></tr>`).join('')}</tbody></table></details>`:''}<p class="note">${fmt(plan.checked,0)} builds evaluated. ${plan.settings.tower?'Final comparison checks every cleared Tower floor. ':''}${plan.settings.objective==='highest'?'Typical best is the geometric mean; its integration uses a 0.125-decade grid. ':''}Forecasts use the same card, border and reward rules as the simulator. Search is approximate.${plan.priceEstimates.length?' Some final-level Corrupted prices are estimated.':''}</p></section>`;
}
function verificationResults(){const v=verification,format=x=>plan.settings.objective==='highest'?'1 in '+short(10**x):fmt(x,3);return `<section class="verification-results"><h3>Simulation check · ${v.runs} runs per build</h3><div class="comparison-metrics"><div><small>Current · simulated</small><b>${format(v.current.mean)}</b></div><div class="optimized"><small>Optimized · simulated</small><b>${format(v.optimized.mean)}</b></div><div><small>Current · forecast</small><b>${planMetric(plan.current)}</b></div><div><small>Optimized · forecast</small><b>${planMetric(plan.result)}</b></div></div><p class="note">Same seeds and session time for both builds.${plan.settings.objective==='highest'?'':' Approximate 95% margin: current ±'+fmt(v.current.error95,3)+', optimized ±'+fmt(v.optimized.error95,3)+'.'} Random runs vary; the forecast drives the recommendation.</p></section>`}
async function verifyPlan(){if(!plan)return;cancelVerification();const id=++verificationId,settings=plan.settings,baseline=plan.original||structuredClone(s),optimized=plan.profile,seed=crypto.getRandomValues(new Uint32Array(1))[0],runs=50,workers=Math.min(runs,8,Math.max(1,(navigator.hardwareConcurrency||4)-1));verifying=true;verification=null;error='';render();
  try{const outputs=[];for(const [i,profile]of [baseline,optimized].entries()){
    if(id!==verificationId)return;
    verificationWorker=runSimulations({id:id*2+i,profile,data,seconds:settings.seconds,runs,seed},{workerCount:workers,onProgress:value=>{if(id!==verificationId)return;const el=root.querySelector('#verification-progress');if(el)el.textContent=`${i===0?'Current':'Optimized'} · ${Math.round(value.value*100)}%`}});
    outputs.push(await verificationWorker.promise);
  }if(id!==verificationId)return;verification=pairedSimulationSummary(outputs[0].runs,outputs[1].runs,settings);verifying=false;verificationWorker=null;render();
  }catch(e){if(id!==verificationId||e.name==='AbortError')return;cancelVerification();error=e.message;render()}
}
function render(){const treeView=root.querySelector('.tree-scroll'),treeScroll=treeView?[treeView.scrollLeft,treeView.scrollTop]:[0,0];for(const el of root.querySelectorAll('details[data-disclosure]'))disclosureState.set(el.dataset.disclosure,el.open);const warnings=profileWarnings(s,data),v=effective(s,data);root.innerHTML=`<main><header><h1>Cardborn Calc</h1><button class="quiet" data-reset>Reset</button></header><nav class="top-nav" aria-label="Calculator tabs">${[['setup','Setup'],['optimizer','Optimizer'],['simulator','Roll Simulator'],['builds','Builds']].map(([id,label])=>`<button data-tab="${id}" class="${id===tab?'active':''}" aria-pressed="${id===tab}">${label}</button>`).join('')}</nav><div class="stats-strip">${LUCKS.map((k,i)=>`<div style="--stat-color:${['#e9eff5','#77dce6','#acbaff','#eec274','#d79af0','#99a3f9'][i]}"><small>${name(k)}</small><b title="${fmt(v[k])}">${short(v[k])}</b></div>`).join('')}</div>${notice?`<p class="message" role="status">${esc(notice)}</p>`:''}${error?`<p class="message" role="alert">${esc(error)}</p>`:''}${warnings.length?`<p class="message" role="alert">${warnings.map(esc).join('<br>')}</p>`:''}<div class="main-grid ${tab!=='setup'?'wide':''}"><div class="setup-column">${tab==='setup'?setupWorkspace():tab==='optimizer'?optimizer():tab==='simulator'?simulator():builds()}</div>${tab!=='setup'?'':`<aside>${tab==='setup'?overview():stats()}</aside>`}</div><footer><span>Cardborn Calc</span><a href="https://daddydrag0.github.io/CardbornTowerCalculator/" target="_blank" rel="noopener">Tower Calculator</a><a href="https://github.com/DaddyDrag0/Cardborn-Stat-Optimizer" target="_blank" rel="noopener">Source</a></footer><div id="tree-tooltip" class="tree-tooltip" role="tooltip" hidden></div><input id="profile-file" type="file" accept="application/json,.json" hidden></main>`;for(const el of root.querySelectorAll('details[data-disclosure]'))if(disclosureState.has(el.dataset.disclosure))el.open=disclosureState.get(el.dataset.disclosure);bind();const nextTree=root.querySelector('.tree-scroll');if(nextTree){nextTree.scrollLeft=treeScroll[0];nextTree.scrollTop=treeScroll[1]}}
function changed(){save();render()}
function update(id,value){if(id==='sim-tower'){s.simulation.tower=value;if(value)s.build.inDungeon=false;changed();return}if(id==='artifact-input'){artifactInput=value;render();return}if(id==='breakdown-stat'){breakdownStat=value;render();return}if(id==='build-index'&&value===''){s.build.index=0;changed();return}if(id==='opt-rarity'){const rarity=parseCompact(value);if(!Number.isFinite(rarity)||rarity<1){error='Enter a rarity such as 1Qa, 100Qi or 1e18.';render();return}s.optimizer.rarity=rarity;changed();return}if(id==='opt-unit'){optUnit=value;render();return}if(id==='opt-objective')s.optimizer.objective=value;else if(id==='opt-match')s.optimizer.match=value;else if(id.startsWith('opt-border-')){const border=id.slice(11);s.optimizer.borders=value?[...s.optimizer.borders,border]:s.optimizer.borders.filter(x=>x!==border)}else if(id==='opt-hours')s.optimizer.seconds=Number(value)*(optUnit==='day'?86400:3600);else if(id.startsWith('opt-component-'))s.optimizer.components[id.slice(14)]=value;else if(id==='global-luck')s.globalLuck=Number(value);else if(id==='roll-counter')s.rollCounter=Number(value);else if(id==='fabled-max'||id==='goal-rarity'){const number=parseCompact(value);if(!Number.isFinite(number)||number<0){error='Enter a rarity such as 500M, 1B, or 1.5B.';render();return}if(id==='fabled-max')s.fabledMax=number;else s.goal.rarity=number;}else if(id.startsWith('currency-'))s.build.currencies[id.slice(9)]=Number(value);else if(id==='rolls'||id==='minutes')s[id]=Number(value);else if(id.startsWith('point-'))s.points[id.slice(6)]=Number(value);else if(id.startsWith('scale-'))s.pointScale[id.slice(6)]=Number(value);else if(id.startsWith('pass-'))s.build.passes[id.slice(5)]=value;else if(id.startsWith('tower-'))s.build.tower[id.slice(6)]=Number(value);else if(id.startsWith('corrupted-')){const upgrade=id.slice(10),result=setCorruptedLevel(s.build,upgrade,value,data);if(result.error){error=result.error;render();return}s.build.corrupted[upgrade]=result.level;s.build.currencies.corrupted=result.balance}else if(id.startsWith('achievement-')){const a=id.slice(12);s.build.achievements=value?[...s.build.achievements,a]:s.build.achievements.filter(x=>x!==a)}else if(id.startsWith('void-'))s.build.void[id.slice(5)]=Number(value);else if(id.startsWith('base-'))s.build.base[id.slice(5)]=Number(value);else if(id.startsWith('build-')){const k=id.slice(6);s.build[k]=['under10M','inDungeon','craftedIndexSpeed'].includes(k)?value:['crafted','craftedTier','craftedIndexOrder','percentOrder'].includes(k)?value:Number(value)}else if(id.startsWith('artifact-')){const k=id.slice(9);s.artifact[k]=k==='rarity'?value:Number(value)/100;if(k==='quality')s.artifact.qualityEdited=true}else if(id.startsWith('potion-')){const category=id.slice(7);s.build.potions=s.build.potions.filter(p=>potionGroup(p,data)!==category);if(value)s.build.potions.push(value)}else if(id.startsWith('set-')){const set=id.slice(4);s.build.sets=value?[...s.build.sets,set]:s.build.sets.filter(x=>x!==set)}else if(id==='weather')s.weather=value;else if(id.startsWith('badge-')){const badge=id.slice(6);s.badges=value?[...s.badges,badge]:s.badges.filter(x=>x!==badge)}else if(id.startsWith('unlock-'))s.unlocks[id.slice(7)]=value;else if(id.startsWith('odds-'))s.odds[id.slice(5)]=Number(value);else if(id.startsWith('border-')){const border=id.slice(7);s.goal.borders=value?[...s.goal.borders,border]:s.goal.borders.filter(x=>x!==border)}else if(id==='goal-kind')s.goal.kind=value;else if(id==='goal-rarity')s.goal.rarity=Number(value);else if(id==='goal-card'){if(!data.cards.some(c=>c.name===value)){error='Choose a card from the list.';render();return}s.goal.card=value}changed()}
function optimize(type){
  cancel();running=true;plan=null;error='';render();
  worker=new Worker('./worker.js?v=9.2',{type:'module'});const id=++job;
  worker.onmessage=e=>{
    if(e.data.id!==id)return;
    if(e.data.type==='progress'){const label=root.querySelector('#optimizer-progress');if(label)label.textContent=`${e.data.value.phase||"Searching"} · ${Math.round((e.data.value.value??e.data.value)*100)}%`;return}
    running=false;if(e.data.type==='error')error=e.data.message;else{plan=e.data.result;showAllChanges=false;verification=null}
    worker?.terminate();worker=null;render();
  };
  worker.onerror=e=>{cancel();error=e.message||'Search failed.';render()};worker.postMessage({id,type,profile:s,data});
}
function bind(){if(simRunning)for(const el of root.querySelectorAll('.tower-settings input'))el.disabled=true;
  bindTreePan();
  root.querySelector('[data-show-changes]')?.addEventListener('click',()=>{showAllChanges=!showAllChanges;render()});root.querySelector('[data-verify-plan]')?.addEventListener('click',verifyPlan);root.querySelector('[data-cancel-verification]')?.addEventListener('click',()=>{cancelVerification();render()});
  root.querySelector('[data-test-plan]')?.addEventListener('click',()=>{const seconds=plan.settings.seconds;s=normalize(plan.profile,data);save();tab='simulator';simDuration=seconds/3600;simUnit='hour';simRuns=1;simView='individual';notice='Recommended build applied.';render();runSimulation()});
  for(const el of root.querySelectorAll('[data-available]'))el.onchange=()=>{const id=el.dataset.item;s.optimizer.relics=s.optimizer.relics.filter(x=>x.id!==id);if(el.checked)s.optimizer.relics.push({id,border:1});changed()};
  for(const el of root.querySelectorAll('[data-owned-border]'))el.onchange=()=>{const id=el.dataset.ownedBorder;s.optimizer.relics=s.optimizer.relics.filter(x=>x.id!==id);s.optimizer.relics.push({id,border:Number(el.value)});changed()};
  root.querySelector('#sim-fixed-seed')?.addEventListener('change',e=>{simFixedSeed=e.target.checked;render()});
  root.querySelector('[data-cancel-optimize]')?.addEventListener('click',()=>{cancel();render()});
  root.querySelector('[data-corrupted-all]')?.addEventListener('change',e=>{if(!e.target.checked)return;const result=buyAllCorrupted(s.build,data);if(result.error){error=result.error;render();return}s.build.corrupted=result.levels;s.build.currencies.corrupted=result.balance;changed()});
  for(const el of root.querySelectorAll('[data-tree-skill]')){const select=()=>{treeSelected=el.dataset.treeSkill;chooseSkill(treeSelected,!s.build.skills.includes(treeSelected))};el.onclick=e=>{if(!treeDragging)select()};el.onpointerenter=el.onpointermove=e=>{if(!treeDragging)showTreeTooltip(el,e)};el.onpointerleave=()=>root.querySelector('#tree-tooltip').hidden=true;el.onfocus=e=>showTreeTooltip(el,e);el.onblur=()=>root.querySelector('#tree-tooltip').hidden=true;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}}
  root.querySelector('[data-clear-skills]')?.addEventListener('click',()=>{s.build.skills=[];changed()});
  for(const el of root.querySelectorAll('[data-shop]'))el.onclick=()=>{const r=shopAction(s.build,el.dataset.shop,el.dataset.upgrade,el.dataset.direction==='max'?'max':Number(el.dataset.direction),data);if(r.error){error=r.error;render();return}s.build[el.dataset.shop][el.dataset.upgrade]=r.level;s.build.currencies[el.dataset.shop]=r.balance;changed()};
  root.querySelector('#dungeon-time')?.addEventListener('change',e=>{const parts=e.target.value.match(/^(\d+):([0-5]\d):([0-5]\d)$/);if(!parts){error='Use hours:minutes:seconds, such as 01:25:30.';render();return}s.build.dungeonSeconds=Math.max(1,Number(parts[1])*3600+Number(parts[2])*60+Number(parts[3]));changed()});
  root.querySelector('#setup-section')?.addEventListener('change',e=>{setupSection=e.target.value;error='';render()});for(const el of root.querySelectorAll('[data-section]'))el.onclick=()=>{setupSection=el.dataset.section;error='';render()};for(const el of root.querySelectorAll('[data-overview]'))el.onclick=()=>{overviewTab=el.dataset.overview;render()};
  root.querySelector('#sim-duration')?.addEventListener('change',e=>{simDuration=Math.max(.001,Number(e.target.value)||1);simulation=null;render()});root.querySelector('#sim-unit')?.addEventListener('change',e=>{simUnit=e.target.value;simulation=null;render()});root.querySelector('#sim-seed')?.addEventListener('change',e=>{simSeed=Math.max(1,Math.min(4294967295,Math.floor(Number(e.target.value)||1)));simulation=null;render()});for(const el of root.querySelectorAll('[data-sim-runs]'))el.onclick=()=>{simRuns=Number(el.dataset.simRuns);simulation=null;render()};root.querySelector('[data-simulate]')?.addEventListener('click',runSimulation);root.querySelector('[data-sim-cancel]')?.addEventListener('click',()=>{cancelSimulation();render()});for(const el of root.querySelectorAll('[data-sim-view]'))el.onclick=()=>{simView=el.dataset.simView;render()};root.querySelector('#sim-run')?.addEventListener('change',e=>{simRun=Number(e.target.value);render()});for(const el of root.querySelectorAll('[data-sim-results]'))el.onclick=()=>{simResultsTab=el.dataset.simResults;render()};root.querySelector('#sim-search')?.addEventListener('input',e=>{const term=e.target.value.toLowerCase();for(const row of root.querySelectorAll('[data-pull-name]'))row.hidden=!row.dataset.pullName.includes(term)});
  root.querySelector('#build-name')?.addEventListener('input',e=>buildName=e.target.value.slice(0,60));root.querySelector('[data-save-build]')?.addEventListener('click',()=>{try{const list=savedBuilds();list.push({name:buildName||'Build '+(list.length+1),profile:structuredClone(s)});localStorage.setItem('cardborn-saved-builds',JSON.stringify(list.slice(-20)));notice='Build saved.';render()}catch{error='Browser storage unavailable. Use Export.';render()}});for(const el of root.querySelectorAll('[data-load-build]'))el.onclick=()=>{s=upgrade(savedBuilds()[Number(el.dataset.loadBuild)].profile);notice='Build loaded.';changed()};for(const el of root.querySelectorAll('[data-delete-build]'))el.onclick=()=>{const list=savedBuilds();list.splice(Number(el.dataset.deleteBuild),1);localStorage.setItem('cardborn-saved-builds',JSON.stringify(list));render()};
for(const el of root.querySelectorAll('[data-field]'))el.onchange=()=>update(el.dataset.field,el.type==='checkbox'?el.checked:el.value);for(const el of root.querySelectorAll('[data-tab]'))el.onclick=()=>{cancel();tab=el.dataset.tab;plan=null;error='';render()};
  for(const el of root.querySelectorAll('[data-skill]'))el.onchange=()=>chooseSkill(el.dataset.skill,el.checked);for(const el of root.querySelectorAll('[data-skill-all]'))el.onclick=()=>{s.build.skills=skillClosure([...s.build.skills,...data.skillNodes.filter(n=>n.branch===el.dataset.skillAll).map(n=>n.id)],data);changed()};for(const el of root.querySelectorAll('[data-skill-clear]'))el.onclick=()=>{for(const node of data.skillNodes.filter(n=>n.branch===el.dataset.skillClear))s.build.skills=removeSkill(s.build.skills,node.id,data);changed()};
  root.querySelector('[data-sets-all]')?.addEventListener('click',()=>{s.build.sets=data.indexSets.map(d=>d.id);changed()});root.querySelector('[data-sets-clear]')?.addEventListener('click',()=>{s.build.sets=[];changed()});root.querySelector('[data-add-relic]')?.addEventListener('click',()=>{const id=Object.keys(data.relics).find(id=>!s.build.relics.some(r=>r.id===id));s.build.relics.push({id,border:1});changed()});for(const el of root.querySelectorAll('[data-relic]'))el.onchange=()=>{s.build.relics[el.dataset.relic][el.dataset.part]=el.dataset.part==='border'?Number(el.value):el.value;changed()};for(const el of root.querySelectorAll('[data-remove-relic]'))el.onclick=()=>{s.build.relics.splice(Number(el.dataset.removeRelic),1);changed()};
  root.querySelector('[data-add-slot]')?.addEventListener('click',()=>{s.artifact.slots.push({id:'Luck',value:5,locked:false});changed()});for(const el of root.querySelectorAll('[data-remove-slot]'))el.onclick=()=>{s.artifact.slots.splice(Number(el.dataset.removeSlot),1);changed()};for(const el of root.querySelectorAll('[data-slot]'))el.onchange=()=>{const slot=s.artifact.slots[el.dataset.slot],part=el.dataset.part,def=data.personalArtifact.stats.find(d=>d.id===slot.id);if(part==='id'){slot.id=el.value;slot.value=data.personalArtifact.stats.find(d=>d.id===el.value)?.min||0;slot.locked=false}else if(part==='locked')slot.locked=el.checked;else{const value=artifactInput==='game'?paRawValue(s,def,Number(el.value),data):artifactInput==='raw'?Number(el.value):def.min+(def.max-def.min)*Number(el.value)/100,f=10**def.decimals;slot.value=Math.floor(value*f+.5)/f}changed()};
  root.querySelector('[data-add-extra]')?.addEventListener('click',()=>{s.build.extras.push({name:'Corrupted Shop / other bonus',stat:'Luck',flat:{Luck:0},percent:{}});changed()});for(const el of root.querySelectorAll('[data-remove-extra]'))el.onclick=()=>{s.build.extras.splice(Number(el.dataset.removeExtra),1);changed()};for(const el of root.querySelectorAll('[data-extra]'))el.onchange=()=>{const e=s.build.extras[el.dataset.extra],part=el.dataset.part;if(part==='name')e.name=el.value;else if(part==='stat'){const old=e.stat;e.stat=el.value;e.flat={[el.value]:e.flat[old]||0};e.percent={[el.value]:LUCKS.includes(el.value)?e.percent[old]||0:0}}else e[part][e.stat]=Number(el.value)/(part==='percent'?100:1);changed()};
  for(const el of root.querySelectorAll('[data-optimize]'))el.onclick=()=>optimize(el.dataset.optimize);root.querySelector('[data-apply-plan]')?.addEventListener('click',()=>{s=normalize(plan.profile,data);notice='Recommended build applied.';changed()});
  root.querySelector('[data-reset]').onclick=()=>{cancel();s=fresh();notice='Setup reset.';changed()};if(root.querySelector('[data-export]'))root.querySelector('[data-export]').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({...s,stats:effective(s,data)},null,2)],{type:'application/json'}));a.href=url;a.download='cardborn-build.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if(root.querySelector('[data-import]'))root.querySelector('[data-import]').onclick=()=>root.querySelector('#profile-file').click();root.querySelector('#profile-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw Error('Profile too large.');const parsed=JSON.parse(await file.text());if(![1,2].includes(parsed.version)||!parsed.stats)throw Error('Choose a Cardborn profile.');s=upgrade(parsed);notice=parsed.version===2?'Build imported.':notice;changed()}catch(e){error=e.message;render()}};
}
function chooseSkill(id,on){const result=skillSelection(s.build,id,on,data);if(result.error){error=result.error;render();return}s.build.skills=result.ids;changed()}
function duration(seconds){return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':')}
function pending(){const remaining=corruptedRemainingCost(s.build,data),allOwned=remaining===0;return panel('Corrupted permanent upgrades',`${field('currency-corrupted','Unspent Corrupted Coins',s.build.currencies.corrupted,{step:1})}<p class="note">Changing levels spends or refunds Coins.</p><label class="check"><input type="checkbox" data-corrupted-all ${allOwned?'checked':''} ${allOwned||s.build.currencies.corrupted<remaining?'disabled':''}><span>Own everything<small>${allOwned?'Maxed':`${fmt(remaining,0)} Coins to max remaining upgrades.`}</small></span></label><div class="shop-grid">${data.corruptedUpgrades.map(d=>{const lv=s.build.corrupted[d.id]||0,cost=corruptedCost(d,lv),refund=corruptedRefund(d,lv);return`<div class="shop-upgrade">${field('corrupted-'+d.id,d.name,lv,{step:1,max:d.maxLevel,help:`${bonuses({[d.stat]:lv*d.gain})} · max ${d.maxLevel}`})}<div class="shop-buttons"><button data-shop="corrupted" data-upgrade="${d.id}" data-direction="-1" ${lv?'':'disabled'}>Refund all +${fmt(refund,0)} Coins</button><button data-shop="corrupted" data-upgrade="${d.id}" data-direction="1" ${lv<d.maxLevel&&s.build.currencies.corrupted>=cost?'':'disabled'}>${lv===d.maxLevel?'Maxed':'+ Buy '+fmt(cost,0)+' Coins'}</button></div></div>`}).join('')}</div>`)}
function achievements(){return panel('Achievements',`<div class="checks">${data.achievements.map(a=>check('achievement-'+a.id,a.name,s.build.achievements.includes(a.id),a.periodic?`×${a.periodic.mult} Luck every ${fmt(a.periodic.every,0)} rolls · unlocks World 8 cards`:bonuses(a.bonus))).join('')}</div>`,{caption:`${s.build.achievements.length}/${data.achievements.length}`})}
function runSimulation(){const seconds=simDuration*({second:1,minute:60,hour:3600,day:86400}[simUnit]);if(s.simulation.tower){try{towerSessionPlan(s.build,seconds)}catch(e){error=e.message;render();return}}if(seconds<1||seconds>172800){error='Choose a duration between 1 second and 2 days.';render();return}const warnings=profileWarnings(s,data);if(warnings.length){error=warnings.join(' ');render();return}cancelSimulation();if(!simFixedSeed)simSeed=crypto.getRandomValues(new Uint32Array(1))[0];simulation=null;simRunning=true;simProgress=0;simParallelism=(Math.floor(seconds/effective(s,data).RollInterval)+(s.simulation.tower?towerSessionPlan(s.build,seconds).cards:0))*simRuns>=100000?Math.min(simRuns,8,Math.max(1,(navigator.hardwareConcurrency||4)-1)):1;error='';render();const id=++simId;
  simWorker=runSimulations({id,profile:s,data,seconds,runs:simRuns,seed:simSeed},{workerCount:simParallelism,onProgress:progress=>{if(id!==simId)return;simProgress=progress.value;const p=root.querySelector('#sim-progress');if(p)p.value=simProgress;const label=root.querySelector('#sim-progress-label');if(label)label.textContent=`${Math.round(simProgress*100)}% · ${fmt(progress.cycles,0)} / ${fmt(progress.total,0)} ${s.simulation.tower?'roll cycles + Tower draws':'cycles'} · ${progress.workers} worker${progress.workers===1?'':'s'}`}});
  simWorker.promise.then(result=>{if(id!==simId)return;simRunning=false;simWorker=null;simulation=result;simRun=0;render()}).catch(e=>{if(id!==simId||e.name==='AbortError')return;cancelSimulation();error=e.message||'Simulation failed.';render()});
}
function towerSettings(seconds=simDuration*({second:1,minute:60,hour:3600,day:86400}[simUnit])){let plan;try{plan=towerSessionPlan(s.build,seconds)}catch{}return `<div class="tower-settings"><h3>Infinite Tower</h3>${check('sim-tower','Include Tower rewards',s.simulation.tower)}${s.simulation.tower?`<div class="grid">${field('build-floor','Cleared floor per Tower run',s.build.floor,{min:1,max:50000,step:1})}<label class="field"><span>Tower run time (hours:minutes:seconds)</span><input id="dungeon-time" value="${duration(s.build.dungeonSeconds)}" placeholder="00:45:00"></label></div>${plan?`<p class="note">${fmt(plan.completedRuns,0)} full Tower run${plan.completedRuns===1?"":"s"}${plan.partialFloor?` + ${fmt(plan.partialFloor,0)} floors`:""} · ${fmt(plan.cards,0)} reward cards per session.</p>`:'<p class="note">Enter a cleared floor from 1 to 50,000.</p>'}<details><summary>Reward model · estimates</summary><p class="note">Floors clear evenly across the entered time, then the Tower restarts. Unfinished runs count cleared floors. Floor bonuses add to normal stats for Tower rewards only. Each reward card is a single draw; extra rolls, periodic boosts and Lucky Hand apply to normal rolls only. Reward-generation rules are server-side and unverified.</p></details>`:''}</div>`}
function simulator(){const v=effective(s,data);return `<div class="sim-config"><section class="panel plain"><div class="section-heading"><h2>Session settings</h2><span class="badge">Roll by roll</span></div><div class="grid"><label class="field"><span>Duration per run</span><div class="duration-input"><input id="sim-duration" type="number" min="0.001" step="any" value="${simDuration}" ${simRunning?'disabled':''}><select id="sim-unit" ${simRunning?'disabled':''}>${[['second','Seconds'],['minute','Minutes'],['hour','Hours'],['day','Days']].map(([id,label])=>`<option value="${id}" ${simUnit===id?'selected':''}>${label}</option>`).join('')}</select></div><small>Up to 2 days per run</small></label><label class="field"><span>Random seed</span><input id="sim-seed" type="number" min="1" max="4294967295" value="${simSeed}" ${simRunning||!simFixedSeed?'disabled':''}><small>${simFixedSeed?'Same seed repeats the run.':'New random seed each run.'}</small></label></div><label class="check"><input id="sim-fixed-seed" type="checkbox" ${simFixedSeed?'checked':''} ${simRunning?'disabled':''}>Use fixed seed</label><span class="field-label">Runs</span><div class="segmented run-options">${[1,50,100,500,1000].map(n=>`<button data-sim-runs="${n}" class="${simRuns===n?'active':''}" ${simRunning?'disabled':''}>${n}</button>`).join('')}</div><div class="build-snapshot"><span><small>ROLL INTERVAL</small><b>${fmt(v.RollInterval,2)}s / cycle</b></span><span><small>WEATHER</small><b>${esc(s.weather)}</b></span><span><small>GLOBAL LUCK</small><b>${fmt(s.globalLuck)}×</b></span><button data-tab="setup">Edit setup</button></div>${towerSettings()}<div class="sim-actions"><button class="primary" data-simulate ${simRunning?'disabled':''}>${simRunning?'Simulating…':'Run simulation'}</button>${simRunning?'<button data-sim-cancel>Cancel</button><progress id="sim-progress" max="1" value="0"></progress><span id="sim-progress-label" role="status">0%</span>':''}</div><p class="note">Every card is rolled individually. ${s.simulation.tower?'Tower bonuses scale by floor and reset each Tower run.':'Stats stay fixed.'} Buffs and weather stay fixed. ${fmt(Math.floor(simDuration*({second:1,minute:60,hour:3600,day:86400}[simUnit])/v.RollInterval)*simRuns,0)} roll cycles requested.</p></section></div>${simulation?simulationResults():`<section class="panel sim-empty"><h2>${simRunning?'Simulating…':'No results yet'}</h2></section>`}`}
function rarityTable(runs,seconds){const rows=rarityResults(runs);return `<table class="rarity-table"><thead><tr><th>Minimum final rarity</th><th>Average pulls in ${time(seconds)}</th><th>Chance of 1+ in ${time(seconds)}</th><th>Total in ${runs.length} run${runs.length===1?'':'s'}</th></tr></thead><tbody>${rows.map(row=>`<tr><td><b>≥ ${short(row.rarity)}</b></td><td>${quantity(row.average)}</td><td>${pct(row.chance)}</td><td>${fmt(row.total,0)}</td></tr>`).join('')}</tbody></table>`}
function simulationResults(){const average=simView==='average',r=average?simulation.aggregate:simulation.runs[simRun],divisor=average?r.runCount:1,maskLabel=mask=>BORDERS.filter((b,i)=>Number(mask)&(1<<i)).join(' + ')||'No border',n=value=>fmt(value/divisor,2),best=r.best;return `<section class="panel plain sim-results"><div class="results-heading"><div><span class="eyebrow">${simulation.runs.length} RUN${simulation.runs.length===1?"":"S"} · ${time(r.seconds)} EACH</span><h2>Simulation results</h2></div><div class="segmented"><button data-sim-view="average" class="${average?'active':''}">Average</button><button data-sim-view="individual" class="${!average?'active':''}">Individual run</button></div>${!average?`<label class="field"><span>View run</span><select id="sim-run">${simulation.runs.map((x,i)=>`<option value="${i}" ${i===simRun?'selected':''}>Run ${i+1}</option>`).join('')}</select></label>`:''}</div><div class="result-metrics">${[['Cards / '+(average?'run':'session'),n(r.cards)],['Roll cycles',n(r.cycles)],['Card types pulled',r.uniqueCards],[average?'Median best rarity':'Seed',average?'1 in '+short([...simulation.runs].map(x=>x.best?.rarity||0).sort((a,b)=>a-b)[Math.floor(simulation.runs.length/2)]):r.seed]].map(([label,value])=>`<div><small>${label}</small><b>${value}</b></div>`).join('')}</div>${r.tower?`<div class="result-metrics">${[['Normal cards',n(r.regularCards)],['Tower cards',n(r.towerCards)],['Full Tower runs',n(r.tower.completedRuns)],['Final partial run','Floor '+fmt(r.tower.partialFloor,0)]].map(([label,value])=>`<div><small>${label}</small><b>${value}</b></div>`).join('')}</div>`:''}<div class="best-pull"><div><small>BEST PULL ${average?'ACROSS ALL RUNS':''}</small><h3>${best?esc(best.name):'No cards pulled'}</h3><p>${best?`${esc(best.borders.join(' + ')||'No border')} · 1 in <b>${short(best.rarity)}</b>`:'Increase the duration to complete a roll cycle.'}</p></div></div><div class="border-metrics">${[...BORDERS,'No border'].map((b,i)=>{const count=b==='No border'?r.combos[0]||0:r.borderTotals[b];return`<div style="--stat-color:${['#77dce6','#acbaff','#eec274','#d79af0','#99a3f9','#a4b3bf'][i]}"><span>${b}</span><b>${n(count)}</b><small>${pct(r.cards?count/r.cards:0)} of cards</small></div>`}).join('')}</div><div class="results-toolbar"><div class="segmented"><button data-sim-results="rarities" class="${simResultsTab==='rarities'?'active':''}">Rarity Results</button><button data-sim-results="cards" class="${simResultsTab==='cards'?'active':''}">Cards pulled</button><button data-sim-results="combos" class="${simResultsTab==='combos'?'active':''}">Border combinations</button></div>${simResultsTab==='cards'?'<input id="sim-search" type="search" aria-label="Search cards" placeholder="Search cards…">':''}</div><div class="table-scroll">${simResultsTab==='rarities'?rarityTable(average?simulation.runs:[simulation.runs[simRun]],r.seconds):simResultsTab==='cards'?`<table class="inventory-table"><thead><tr><th>Card</th><th>Rarity with borders</th><th>${average?'Avg / run':'Pulled'}</th>${average?'<th>Runs hit</th>':''}</tr></thead><tbody>${r.inventory.map(row=>`<tr data-pull-name="${esc(row.name.toLowerCase())}"><td><b>${esc(row.name)}</b><small>${esc(row.borders.join(' + ')||'No border')} · base 1 in ${short(row.baseRarity)}</small></td><td>1 in ${short(row.rarity)}</td><td>${n(row.count)}</td>${average?`<td>${row.runsHit} / ${r.runCount}</td>`:''}</tr>`).join('')||'<tr><td colspan="4">No cards pulled.</td></tr>'}</tbody></table>`:`<table><thead><tr><th>Combination</th><th>${average?'Avg / run':'Pulled'}</th><th>Share</th></tr></thead><tbody>${Object.entries(r.combos).sort((a,b)=>b[1]-a[1]).map(([mask,count])=>`<tr><td>${esc(maskLabel(mask))}</td><td>${n(count)}</td><td>${pct(count/r.cards)}</td></tr>`).join('')}</tbody></table>`}</div><p class="note">${simResultsTab==='rarities'?'Counts use final rarity after borders; chance is the share of runs with at least one qualifying pull.':'Border totals overlap when borders stack.'}</p></section>`}
function savedBuilds(){try{const a=JSON.parse(localStorage.getItem('cardborn-saved-builds')||'[]');return Array.isArray(a)?a.filter(x=>x&&typeof x.name==='string'&&x.profile).slice(-20):[]}catch{return[]}}
function builds(){return `<section class="panel plain"><h2>Builds</h2><div class="optimizer-buttons"><button data-export>Export current build</button><button data-import>Import build</button></div><label class="field"><span>Build name</span><input id="build-name" maxlength="60" value="${esc(buildName)}"></label><button data-save-build>Save current build</button>${savedBuilds().map((b,i)=>`<p class="saved-build"><b>${esc(b.name)}</b><button data-load-build="${i}">Load</button><button data-delete-build="${i}">Delete</button></p>`).join('')}</section>`}
function bindTreePan(){const view=root.querySelector('.tree-scroll');if(!view)return;let start=null;view.onpointerdown=e=>{if(e.button!==0)return;treeDragging=false;start={id:e.pointerId,x:e.clientX,y:e.clientY,left:view.scrollLeft,top:view.scrollTop};};view.onpointermove=e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(!treeDragging&&Math.hypot(dx,dy)<5)return;if(!treeDragging){treeDragging=true;view.setPointerCapture(e.pointerId);view.classList.add('dragging');root.querySelector('#tree-tooltip').hidden=true}view.scrollLeft=start.left-dx;view.scrollTop=start.top-dy;e.preventDefault()};const end=e=>{if(!start||e.pointerId!==start.id)return;start=null;view.classList.remove('dragging');if(view.hasPointerCapture(e.pointerId))view.releasePointerCapture(e.pointerId);setTimeout(()=>treeDragging=false,0)};view.onpointerup=view.onpointercancel=end;view.addEventListener('click',e=>{if(treeDragging){e.preventDefault();e.stopImmediatePropagation()}},true)}
function showTreeTooltip(el,event){const n=data.skillNodes.find(n=>n.id===el.dataset.treeSkill),tip=root.querySelector('#tree-tooltip');tip.innerHTML=`<b>${esc(n.name)}</b><p>${esc(n.desc)}</p><small>${n.cost} SP · ${s.build.skills.includes(n.id)?'Owned':'Unowned'}</small>`;tip.hidden=false;const rect=el.getBoundingClientRect(),x=event.clientX??rect.right,y=event.clientY??rect.bottom;tip.style.left=Math.max(8,Math.min(x+14,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,Math.min(y+14,innerHeight-tip.offsetHeight-8))+'px'}
render();
